  doa, dia, addra, bytea, bytewea, csa, wea, clka, rsta, ocea,
  dob, dib, addrb, byteb, byteweb, csb, web, clkb, rstb, oceb
  );

output  [15:0] doa;              //  [Template:Port A reads data. ]
output  [15:0] dob;              //  [Template:Port B reads data. ]
input   [15:0] dia;              //  [Template:Port A writes data.]
input   [15:0] dib;              //  [Template:Port B writes data.]
input   [10:0] addra;            //  [Template:Port A writes the address.]
input   [10:0] addrb;            //  [Template:Port B writes the address.]
input   bytea;   	// bytewea=0, 16bit; bytewea=1&&bytea=0, lower 8bit write, higher 8bit no operation; bytewea=1&&bytea=1, higher 8bit write, low 8bit nochange  [Template:bytewea=0, 16bit; bytewea=1&&bytea=0, lower 8bit write, higher 8bit no operation; bytewea=1&&bytea=1, higher 8bit write, low 8bit nochange.]
input   bytewea;  // bytewea=0, 16bit; bytewea=1&&bytea=0, lower 8bit write, higher 8bit no operation; bytewea=1&&bytea=1, higher 8bit write, low 8bit nochange  [Template:bytewea=0, 16bit; bytewea=1&&bytea=0, lower 8bit write, higher 8bit no operation; bytewea=1&&bytea=1, higher 8bit write, low 8bit nochange.]
input   byteb;     // for port-b byte write enable, function is same as bytewea		[Template:for port-b byte write enable, function is same as bytewea.]
input   byteweb;  // for port-b byte write enable, function is same as bytewea		[Template:for port-b byte write enable, function is same as bytewea.]
input   csa;   //	[Template:Port A chip select signal.]
input   wea;   //	[Template:Port A write enable signal.]
input   csb;   //	[Template:Port B chip select signal.]
input   web;   //  [Template:Port B write enable signal.]
input   clka;  //	[Template:Port A clock.]
input   rsta;  //  [Template:Port A reset signal.]
input   clkb;  //	[Template:Port B clock.]
input   rstb;  //  [Template:Port B reset signal.]
input   ocea;  // port a output register ce input when REGMODE_A=="OUTREG"  [Template:Port A output register ce input when REGMODE_A=="OUTREG".]
input   oceb;  // port b output register ce input when REGMODE_B=="OUTREG"  [Template:Port B output register ce input when REGMODE_B=="OUTREG".]

parameter MODE = "DP16K";              //  "DP16K", "SP16K".          [Template:BRAM mode setting,for DATA_WIDTH = 18, MODE must be "PDPW8K" or "FIFO8K".]
parameter DATA_WIDTH_A = "16";         //  "8", "16".                 [Template:Bit width of write data.          ]
parameter DATA_WIDTH_B = "16";         //  "8", "16".                 [Template:Bit width of read data.           ]
                                       //  "NOREG", "OUTREG".         [Template:Output register mode of port A.   ]
parameter REGMODE_A = "NOREG";         //  "NOREG", "OUTREG".         [Template:Output register mode of port B.   ]
parameter REGMODE_B = "NOREG";         //  "NORMAL", "WRITETHROUGH".  [Template:Write data mode of port A.        ]
parameter WRITEMODE_A = "NORMAL";      //  "NORMAL", "WRITETHROUGH".  [Template:Write data mode of port B.        ]
parameter WRITEMODE_B = "NORMAL";      //  "SYNC", "ASYNC".           [Template:Reset mode.                       ]
parameter SRMODE = "SYNC";             //  "0", "1", "INV", "SIG".    [Template:Clock select mux of port A.       ]
parameter CSAMUX = "SIG";              //  "0", "1", "INV", "SIG".    [Template:Clock select mux of port B.       ]
parameter CSBMUX = "SIG";              //  "0", "1", "INV", "SIG".    [Template:Output clock enable mux of port A.]
parameter OCEAMUX = "SIG";             //  "0", "1", "INV", "SIG".    [Template:Output clock enable mux of port B.]
parameter OCEBMUX = "SIG";             //  "0", "1", "INV", "SIG".    [Template:Reset mux of port A.              ]
parameter RSTAMUX = "SIG";             //  "0", "1", "INV", "SIG".    [Template:Reset mux of port B.              ]
parameter RSTBMUX = "SIG";             //  "0", "1", "INV", "SIG".    [Template:Clock mux of port A.              ]
parameter CLKAMUX = "SIG";             //  "0", "1", "INV", "SIG".    [Template:Clock mux of port B.              ]
parameter CLKBMUX = "SIG";             //  "0", "1", "INV", "SIG".    [Template:Write enable mux of port A.       ]
parameter WEAMUX = "SIG";              //  "0", "1", "INV", "SIG".    [Template:Write enable mux of port B.       ]
parameter WEBMUX = "SIG";              //  "ON", "OFF".               [Template:Backward read enable.             ]
parameter READBACK = "OFF";         

